<script setup lang="ts">
import { cloneTracker } from '@/types/trackers'
import { ref } from 'vue'
import AppSheet from '@/components/shared/AppSheet.vue'
import TrackerDesignEditor from './TrackerDesignEditor.vue'
import { saveTracker, trackerError } from '@/services/trackers.service'
import { kindLabels, type CreativeTracker, type TrackerField } from '@/types/trackers'
const props=withDefaults(defineProps<{initial:Omit<CreativeTracker,'user_id'|'created_at'>;allowKindChoice?:boolean;customize?:boolean}>(),{allowKindChoice:false,customize:false})
const emit=defineEmits<{saved:[CreativeTracker];close:[]}>()
const draft=ref(cloneTracker(props.initial)),busy=ref(false),uploading=ref(false),error=ref('')
const direction=ref(draft.value.config.goal?.direction||'observe'),target=ref(draft.value.config.goal?.target||0)
function addCategory(){draft.value.config.categories.push({id:crypto.randomUUID(),label:'New feeling',color:'#9abcc5'})}
function addField(){draft.value.config.fields.push({id:crypto.randomUUID(),label:'My field',type:'text',unit:'',options:[],max:5})}
function fieldOptions(field:TrackerField,event:Event){field.options=(event.target as HTMLInputElement).value.split(',').map(v=>v.trim()).filter(Boolean)}
function kindChange(){
 const kind=draft.value.kind
 if(kind==='sleep'){draft.value.unit='hours';draft.value.config.multiple=true}
 else if(kind==='steps'){draft.value.unit='steps';draft.value.config.multiple=false;draft.value.config.aggregation='latest'}
 else {draft.value.config.multiple=false}
 if(kind==='category'&&!draft.value.config.categories.length)addCategory()
 if(kind==='custom'&&!draft.value.config.fields.length)addField()
}
async function save(){
 if(busy.value||uploading.value)return
 error.value='';busy.value=true
 draft.value.config.goal=direction.value==='observe'?null:{direction:direction.value as 'at_least'|'at_most',target:Number(target.value)}
 try{emit('saved',await saveTracker(draft.value))}catch(e){error.value=trackerError(e)}finally{busy.value=false}
}
</script>
<template><AppSheet :model-value="true" :title="initial.is_template?'Personal template':'Make it your tracker'" @update:model-value="emit('close')"><form id="tracker-definition-form" class="tracker-form" @submit.prevent="save"><label>Tracker name<input v-model="draft.name" required maxlength="100" placeholder="A little thing I want to notice" /></label><label v-if="allowKindChoice">How will you log it?<select v-model="draft.kind" @change="kindChange"><option v-for="(label,kind) in kindLabels" :key="kind" :value="kind">{{label}}</option></select></label><label v-if="!['habit','category','custom','sleep','steps'].includes(draft.kind)">Unit<input v-model="draft.unit" maxlength="30" placeholder="cups, mL, minutes…" /></label><details v-if="!['habit','category','custom'].includes(draft.kind)" class="optional-goal"><summary>Optional goal</summary><fieldset><legend class="sr-only">A goal, only if you want one</legend><label>What would you like to do?<select v-model="direction"><option value="observe">Simply observe</option><option value="at_least">Reach at least</option><option value="at_most">Stay within a limit</option></select></label><label v-if="direction!=='observe'">Target ({{draft.unit||'units'}})<input v-model.number="target" type="number" min="0" step="any" required /></label><p class="form-help">Your preferences, without scores or judgment. Changes apply from today; past records keep their original goal.</p></fieldset></details><fieldset v-if="draft.kind==='category'"><legend>Your color key</legend><div v-for="(category,i) in draft.config.categories" :key="category.id" class="category-definition"><input v-model="category.color" type="color" :aria-label="'Color for '+category.label" /><input v-model="category.label" required maxlength="80" :aria-label="'Category '+(i+1)" /><button type="button" :aria-label="'Remove '+category.label" @click="draft.config.categories.splice(i,1)">×</button></div><button v-if="draft.config.categories.length<12" type="button" class="secondary" @click="addCategory">＋ Add a category</button></fieldset><fieldset v-if="draft.kind==='custom'"><legend>The things you want to record</legend><div v-for="(field,i) in draft.config.fields" :key="field.id" class="field-definition"><label>Field {{i+1}}<input v-model="field.label" required maxlength="80" /></label><label>Type<select v-model="field.type"><option value="checkbox">Yes / no</option><option value="number">Number</option><option value="duration">Duration (minutes)</option><option value="rating">Rating</option><option value="choice">One choice</option><option value="multi">Several choices</option><option value="text">A short note</option></select></label><label v-if="field.type==='number'">Unit<input v-model="field.unit" maxlength="30" /></label><label v-if="field.type==='choice'||field.type==='multi'">Choices, separated by commas<input :value="field.options.join(', ')" required @change="fieldOptions(field,$event)" /></label><label v-if="field.type==='rating'">Rating scale: 1 to<input v-model.number="field.max" type="number" min="2" max="10" /></label><button type="button" class="text-action" @click="draft.config.fields.splice(i,1)">Remove this field</button></div><button v-if="draft.config.fields.length<12" class="secondary" type="button" @click="addField">＋ Add a field</button><label class="check-label"><input v-model="draft.config.multiple" type="checkbox" /> Allow several entries in one day</label><p class="form-help">Different fields keep separate units. Repeated custom entries are listed individually; unrelated measurements are never added together.</p></fieldset><details class="appearance-details" :open="customize"><summary>✎ Paper, lettering &amp; stickers</summary><TrackerDesignEditor v-model="draft.design" @busy="uploading=$event" /></details><p v-if="error" role="alert" class="tracker-error">{{error}}</p></form><template #footer><div class="sheet-actions"><button type="button" class="secondary" :disabled="busy||uploading" @click="emit('close')">Cancel</button><button type="submit" form="tracker-definition-form" class="primary" :disabled="busy||uploading">{{busy?'Saving…':uploading?'Uploading…':'Keep this tracker'}}</button></div></template></AppSheet></template>
<style scoped>
.tracker-form{display:grid;gap:17px}.tracker-form label{display:grid;gap:7px;color:#655641;font-size:13px}.tracker-form input:not([type=checkbox]):not([type=color]),.tracker-form select{width:100%;min-height:46px;padding:10px 12px;border:1px solid #d8cbb5;background:#fffdf6;border-radius:4px;color:#514b40;font-size:16px}.tracker-form fieldset{padding:14px;border:1px solid #ded3be;border-radius:6px;display:grid;gap:12px}.tracker-form legend{padding:0 6px;font:19px 'Crimson Text',Georgia,serif;color:#754253}.tracker-form legend small{display:block;font:10px 'Inter',sans-serif;color:#9b896b}.form-help{font-size:12px;color:#958064;line-height:1.65;margin:0}.category-definition{display:grid;grid-template-columns:44px minmax(0,1fr) 44px;gap:7px;align-items:center}.category-definition input[type=color]{width:44px;height:44px;padding:3px;border:1px solid #cdbfa6}.category-definition button{min-height:44px;font-size:23px;color:#85465c}.field-definition{display:grid;gap:10px;padding-bottom:15px;border-bottom:1px dashed #d4c6ab}.tracker-form .check-label{display:flex;align-items:center;gap:8px;margin-top:8px}.check-label input{width:20px;height:20px;accent-color:#74283c}.appearance-details{padding:12px;border:1px solid #d5c8af;border-radius:6px}.optional-goal summary{cursor:pointer;min-height:44px;display:flex;align-items:center;font-size:13px;color:#796548}.optional-goal summary::before{content:"+";margin-right:8px}.optional-goal[open] summary::before{content:"−"}.appearance-details summary{min-height:40px;cursor:pointer;font:20px 'Crimson Text',Georgia,serif;color:#754253}.secondary,.primary{min-height:44px;padding:10px 16px;border-radius:4px;font-size:13px;cursor:pointer}.secondary{border:1px solid #d0c1a6;background:#f3eddf;color:#78523c}.primary{border:1px solid #71263b;background:#79283e;color:#fff8e9}.text-action{min-height:44px;justify-self:start;color:#8a4156;font-size:12px}.sheet-actions{display:flex;justify-content:space-between;gap:10px}.tracker-error{font-size:13px;background:#f4e2dc;color:#8e364c;padding:12px;border-radius:4px;line-height:1.6}button:disabled{opacity:.5;cursor:wait}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #8c5d70;outline-offset:3px}
</style>
